function migrateGenerators(generators: Generators): boolean {
  const flatOld = generators[OLD_FLAT_KEY] as Generators | undefined;
  const nestedOld = generators[COLLECTION]?.[OLD_GENERATOR] as
    | Generators
    | undefined;

  if (!flatOld && !nestedOld) {
    // No old ngrx defaults present in either format; leave untouched.
    return false;
  }

  // When both formats coexist, the flat format takes precedence.
  const oldOptions: Generators = { ...(nestedOld ?? {}), ...(flatOld ?? {}) };
  const sourceIsFlat = !!flatOld;

  const rootStoreOptions = pick(oldOptions, ROOT_STORE_OPTIONS);

  const featureStoreOptions = pick(oldOptions, FEATURE_STORE_OPTIONS);
  // Rename `module` to `parent`; `module` takes precedence over `parent`.
  if ('module' in oldOptions) {
    featureStoreOptions.parent = oldOptions.module;
  } else if ('parent' in oldOptions) {
    featureStoreOptions.parent = oldOptions.parent;
  }
  // The obsolete `root` toggle is dropped entirely.

  writeTarget(generators, ROOT_STORE_GENERATOR, rootStoreOptions, sourceIsFlat);
  writeTarget(
    generators,
    FEATURE_STORE_GENERATOR,
    featureStoreOptions,
    sourceIsFlat
  );

  // Remove the old ngrx defaults.
  delete generators[OLD_FLAT_KEY];
  if (generators[COLLECTION]) {
    delete generators[COLLECTION][OLD_GENERATOR];
    // If the nested collection is now empty, remove it entirely.
    if (Object.keys(generators[COLLECTION]).length === 0) {
      delete generators[COLLECTION];
    }
  }

