  let useNested: boolean;
  if (existingNested) {
    useNested = true;
  } else if (existingFlat) {
    useNested = false;
  } else {
    useNested = !sourceIsFlat;
  }

  const existing = useNested ? existingNested : existingFlat;
  // Merge migrated options in, letting user-set existing values take priority.
  const merged: Generators = { ...migratedOptions, ...(existing ?? {}) };

  if (Object.keys(merged).length === 0) {
    // Nothing to write; don't create empty defaults.
    return;
  }

  if (useNested) {
    generators[COLLECTION] ??= {};
    generators[COLLECTION][target] = merged;
  } else {
    generators[flatKey] = merged;
  }
