+const COLLECTION='@nx/angular', OLD='ngrx', ROOT='ngrx-root-store', FEAT='ngrx-feature-store';
+const OLD_FLAT=`${COLLECTION}:${OLD}`;
+const ROOT_OPTS=['facade','minimal','directory'], FEAT_OPTS=['facade','barrels','directory'];
+function pick(s,keys){const r={};for(const k of keys)if(k in s)r[k]=s[k];return r;}
+function writeTarget(g,target,mig,srcFlat){
+  const flatKey=`${COLLECTION}:${target}`;
+  const eF=g[flatKey], eN=g[COLLECTION]?.[target];
+  let useNested; if(eN)useNested=true; else if(eF)useNested=false; else useNested=!srcFlat;
+  const existing=useNested?eN:eF;
+  const merged={...mig,...(existing??{})};
+  if(Object.keys(merged).length===0)return;
+  if(useNested){g[COLLECTION]??={};g[COLLECTION][target]=merged;}else g[flatKey]=merged;
+}
+function mig(g){
+  const flatOld=g[OLD_FLAT], nestedOld=g[COLLECTION]?.[OLD];
+  if(!flatOld&&!nestedOld)return false;
+  const old={...(nestedOld??{}),...(flatOld??{})};
+  const srcFlat=!!flatOld;
+  const root=pick(old,ROOT_OPTS);
+  const feat=pick(old,FEAT_OPTS);
+  if('module' in old)feat.parent=old.module; else if('parent' in old)feat.parent=old.parent;
+  writeTarget(g,ROOT,root,srcFlat); writeTarget(g,FEAT,feat,srcFlat);
+  delete g[OLD_FLAT];
+  if(g[COLLECTION]){delete g[COLLECTION][OLD]; if(Object.keys(g[COLLECTION]).length===0)delete g[COLLECTION];}
+  return true;
+}
+function t(name,input,check){const g=JSON.parse(JSON.stringify(input));const r=mig(g);console.log(name, check(g,r)?'PASS':'FAIL', JSON.stringify(g));}
+
+// no generators ngrx
+t('no-ngrx',{'@nx/angular:library':{}},(g,r)=>r===false&&JSON.stringify(g)==='{"@nx/angular:library":{}}');
+// flat full
+t('flat',{'@nx/angular:ngrx':{facade:true,minimal:false,directory:'d',barrels:true,module:'m',root:true}},
+  (g)=>!g['@nx/angular:ngrx']
+    && JSON.stringify(g['@nx/angular:ngrx-root-store'])===JSON.stringify({facade:true,minimal:false,directory:'d'})
+    && JSON.stringify(g['@nx/angular:ngrx-feature-store'])===JSON.stringify({facade:true,barrels:true,directory:'d',parent:'m'}));
+// nested
+t('nested',{'@nx/angular':{ngrx:{facade:true,directory:'d'}}},
+  (g)=>!g['@nx/angular']?.ngrx
+    && JSON.stringify(g['@nx/angular']['ngrx-root-store'])===JSON.stringify({facade:true,directory:'d'})
+    && JSON.stringify(g['@nx/angular']['ngrx-feature-store'])===JSON.stringify({facade:true,directory:'d'}));
+// nested empty collection cleanup (only root option)
+t('nested-root-only-drop',{'@nx/angular':{ngrx:{root:true}}},
+  (g)=>g['@nx/angular']===undefined);
+// flat root only -> no new keys, old removed
+t('flat-root-only',{'@nx/angular:ngrx':{root:true}},
+  (g)=>Object.keys(g).length===0);
+// flat overrides nested
+t('coexist',{'@nx/angular:ngrx':{facade:true},'@nx/angular':{ngrx:{facade:false,directory:'d'}}},
+  (g)=>!g['@nx/angular:ngrx'] && !g['@nx/angular']?.ngrx
+    && g['@nx/angular:ngrx-root-store'].facade===true
+    && g['@nx/angular:ngrx-feature-store'].facade===true);
+// merge existing new key, user priority
+t('merge-existing',{'@nx/angular:ngrx':{facade:true,directory:'x'},'@nx/angular:ngrx-root-store':{directory:'user',minimal:true}},
+  (g)=>JSON.stringify(g['@nx/angular:ngrx-root-store'])===JSON.stringify({facade:true,directory:'user',minimal:true}));
+// existing nested new key -> nested output
+t('existing-nested-newkey',{'@nx/angular:ngrx':{facade:true},'@nx/angular':{'ngrx-root-store':{minimal:false}}},
+  (g)=>g['@nx/angular:ngrx-root-store']===undefined
+    && JSON.stringify(g['@nx/angular']['ngrx-root-store'])===JSON.stringify({facade:true,minimal:false}));
+// module+parent precedence
+t('module-parent',{'@nx/angular:ngrx':{module:'m',parent:'p'}},
+  (g)=>g['@nx/angular:ngrx-feature-store'].parent==='m' && !('parent' in (g['@nx/angular:ngrx-root-store']||{})));
+// parent only
+t('parent-only',{'@nx/angular:ngrx':{parent:'p'}},
+  (g)=>g['@nx/angular:ngrx-feature-store'].parent==='p');
+// nested with sibling preserved
+t('sibling-preserved',{'@nx/angular':{ngrx:{root:true},application:{x:1}}},
+  (g)=>JSON.stringify(g['@nx/angular'])===JSON.stringify({application:{x:1}}));
